import os
import sqlite3
import hashlib
import hmac
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/tmp/app.db'
SECRET_SIGNING_KEY = os.environ.get('SIGNING_KEY', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT UNIQUE, password_hash TEXT, role TEXT DEFAULT "user", api_key TEXT)')
        g.db.execute('CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT, content TEXT, classification TEXT DEFAULT "internal")')
        g.db.commit()
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(req):
    token = req.headers.get('X-Session-Token', '')
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 3:
        return None
    user_id, timestamp, signature = parts
    # Timing-safe comparison intentionally used
    expected = hmac.new(SIGNING_KEY.encode(), f"{user_id}:{timestamp}".encode(), hashlib.sha256).hexdigest()
    if hmac.compare_digest(signature, expected):
        return int(user_id)
    return None

@app.route('/api/documents/search', methods=['GET'])
def search_documents():
    """Search documents by title. Supports filtering by classification level."""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    # Validate API key
    cursor = db.execute('SELECT id, role FROM users WHERE api_key = ?', (api_key,))
    user = cursor.fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403

    user_id, role = user
    search_term = request.args.get('q', '')
    classification = request.args.get('classification', 'internal')

    # Build query with user's access scope
    if role == 'admin':
        query = f"SELECT id, title, classification FROM documents WHERE title LIKE '%{search_term}%' AND classification = '{classification}'"
    else:
        query = f"SELECT id, title, classification FROM documents WHERE owner_id = {user_id} AND title LIKE '%{search_term}%' AND classification = '{classification}'"

    try:
        results = db.execute(query).fetchall()
        return jsonify({'results': [{'id': r[0], 'title': r[1], 'classification': r[2]} for r in results]})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    cursor = db.execute('SELECT id, role FROM users WHERE api_key = ?', (api_key,))
    user = cursor.fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403

    user_id, role = user
    if role == 'admin':
        doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    else:
        doc = db.execute('SELECT * FROM documents WHERE id = ? AND owner_id = ?', (doc_id, user_id)).fetchone()

    if not doc:
        return jsonify({'error': 'Not found'}), 404
    return jsonify({'id': doc[0], 'owner_id': doc[1], 'title': doc[2], 'content': doc[3], 'classification': doc[4]})

@app.route('/api/documents', methods=['POST'])
def create_document():
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    cursor = db.execute('SELECT id, role FROM users WHERE api_key = ?', (api_key,))
    user = cursor.fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403

    data = request.get_json()
    title = data.get('title', '')
    content = data.get('content', '')
    classification = data.get('classification', 'internal')

    db.execute('INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)',
               (user[0], title, content, classification))
    db.commit()
    return jsonify({'status': 'created'}), 201

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
